import { FormEvent, InputHTMLAttributes, ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Link, Navigate, NavLink, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import QRCode from 'qrcode';
import { api, session } from './api';
import './checkin.css';

type User={id:string;tenantId:string;name:string;username:string;role:string;tenantName:string};
type Permission='events.manage'|'registrations.view'|'orders.view'|'checkin.manage'|'reports.view'|'members.manage';
type Member={id:string;name:string;username:string|null;mobile:string|null;role:string;permissions:Permission[];status:'active'|'disabled';last_login_at:string|null};
type TenantSettings={id:string;name:string;support_contact:string;timezone:'Asia/Shanghai';valid_until:string|null;status:'active'|'suspended';created_at:string};
type EventItem={id:string;title:string;slug:string;venue:string;starts_at:string;ends_at:string;status:string;capacity:number;sold_count:number};
type TicketType={id:string;name:string;price_cents:number;capacity:number;sold_count:number;sale_starts_at:string;sale_ends_at:string};
type RegistrationField={id:string;key:string;label:string;type:'text'|'mobile'|'email'|'number'|'select'|'textarea';required:boolean;enabled:boolean;system?:boolean;placeholder?:string;options?:string[]};
type EventDetail=EventItem&{description:string;hero_color:string;form_background_color:string;registration_form:RegistrationField[];ticketTypes:TicketType[];metrics:{registrations:number;paidAmountCents:number;issued:number;checkedIn:number}};
type CheckinPoint={id:string;name:string;active:boolean;created_at:string;staff:Array<{id:string;name:string;mobile:string|null}>};
type CheckinStaff={id:string;name:string;mobile:string|null;role:string;can_checkin:boolean;point_ids:string[]};
type CreditEntry={id:string;change:number;kind:string;reference:string;note:string;created_at:string};
type CreditWallet={balance:number;reserved:number;available:number;entries:CreditEntry[]};

function DateTimeInput(props:InputHTMLAttributes<HTMLInputElement>){const inputRef=useRef<HTMLInputElement>(null);function openPicker(){try{inputRef.current?.showPicker?.()}catch{/* Native picker is unavailable in some browsers. */}}return <span className="date-time-field" onClick={openPicker}><input {...props} ref={inputRef} type="datetime-local"/></span>}

function Login({onLogin}:{onLogin:(user:User)=>void}){
  type Mode='login'|'register'|'resetRequest'|'resetConfirm';
  const[mode,setMode]=useState<Mode>(new URLSearchParams(window.location.search).has('register')?'register':'login');
  const[error,setError]=useState('');const[notice,setNotice]=useState('');const[loading,setLoading]=useState(false);const[resetMobile,setResetMobile]=useState('');
  function switchMode(next:Mode){setMode(next);setError('');setNotice('')}
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setLoading(true);setError('');setNotice('');const form=new FormData(e.currentTarget);try{if(mode==='login'||mode==='register'){const payload=mode==='login'?{username:form.get('username'),password:form.get('password')}:{tenantName:form.get('tenantName'),name:form.get('name'),mobile:form.get('mobile'),password:form.get('password')};const result=await api<{token:string;user:User}>(mode==='login'?'/auth/login':'/auth/register',{method:'POST',body:JSON.stringify(payload)});session.set(result.token);onLogin(result.user);return}if(mode==='resetRequest'){const mobile=String(form.get('mobile'));const result=await api<{message:string;debugCode?:string}>('/auth/password-reset/request',{method:'POST',body:JSON.stringify({mobile})});setResetMobile(mobile);setNotice(result.debugCode?`${result.message} 开发环境验证码：${result.debugCode}`:result.message);setMode('resetConfirm');return}const result=await api<{message:string}>('/auth/password-reset/confirm',{method:'POST',body:JSON.stringify({mobile:form.get('mobile'),code:form.get('code'),password:form.get('password')})});setNotice(result.message);setMode('login')}catch(e){setError((e as Error).message)}finally{setLoading(false)}}
  const isReset=mode==='resetRequest'||mode==='resetConfirm';
  const title=mode==='login'?'登录活动管理平台':mode==='register'?'免费创建工作空间':mode==='resetRequest'?'找回密码':'验证短信验证码';
  return <div className="login">
    <section className="login-art">
      <Link to="/" className="brand light auth-brand-link" aria-label="EventVivid，返回首页"><b>EV</b><span>EventVivid<small>ORGANIZER</small></span></Link>
      <div className="art-copy"><p className="kicker">CREATE · CONNECT · CELEBRATE</p><h1>把复杂会务，<br/>变成清晰节奏。</h1><p>从活动发布、报名交易到现场入场，让团队在一处掌控每个关键节点。</p></div>
      <div className="art-stats"><span><b>01</b>活动策划</span><span><b>02</b>报名交易</span><span><b>03</b>现场执行</span></div>
    </section>
    <section className="login-form">
      <nav className="auth-top-links" aria-label="页面导航"><Link to="/">返回首页</Link>{mode==='register'&&<Link to="/pricing">查看价格</Link>}<ContactSupport className="auth-contact-button"/></nav>
      <div className="auth-mobile-header"><Link to="/" className="brand dark auth-brand-link" aria-label="EventVivid，返回首页"><b>EV</b><span>EventVivid</span></Link><div><Link to="/">返回首页</Link><ContactSupport className="auth-contact-button"/></div></div>
      <form key={mode} onSubmit={submit}>
        <h2>{title}</h2>
        <p>{mode==='login'?'使用注册手机号登录':mode==='register'?'注册即赠送 100 张电子票额度，成功出票才扣减。':mode==='resetRequest'?'输入注册手机号，我们将发送验证码。':'输入短信验证码并设置新密码。'}</p>
        {mode==='register'&&<><label>企业或组织名称<input name="tenantName" required minLength={2} autoFocus placeholder="例如：星河科技"/></label><label>管理员姓名<input name="name" required minLength={2} placeholder="例如：张三"/></label></>}
        {mode==='login'?<label>手机号<input name="username" type="tel" required pattern="1[3-9][0-9]{9}" autoFocus autoComplete="tel" placeholder="请输入 11 位手机号"/></label>:<label>手机号<input name="mobile" type="tel" required pattern="1[3-9][0-9]{9}" defaultValue={resetMobile} autoFocus={mode!=='resetConfirm'} autoComplete="tel" placeholder="请输入 11 位手机号"/></label>}
        {mode==='resetConfirm'&&<label>短信验证码<input name="code" required inputMode="numeric" pattern="[0-9]{6}" autoComplete="one-time-code" placeholder="请输入 6 位验证码"/></label>}
        {mode!=='resetRequest'&&<label>{mode==='register'?'设置密码':mode==='resetConfirm'?'新密码':'密码'}<input name="password" type="password" required minLength={8} autoComplete={mode==='login'?'current-password':'new-password'} placeholder={mode==='login'?'••••••••••••':'至少 8 位'}/></label>}
        {error&&<div className="alert">{error}</div>}{notice&&<div className="notice auth-notice">{notice}</div>}
        <button className="primary" disabled={loading}>{loading?'处理中…':mode==='login'?'进入活动平台':mode==='register'?'注册并领取 100 张额度':mode==='resetRequest'?'获取验证码':'重置密码'}</button>
        {mode==='login'&&<div className="auth-links"><button className="auth-switch" type="button" onClick={()=>switchMode('resetRequest')}>忘记密码？</button><button className="auth-switch" type="button" onClick={()=>switchMode('register')}>免费注册</button></div>}
        {mode!=='login'&&<button className="auth-switch" type="button" onClick={()=>switchMode('login')}>返回登录</button>}
        {mode==='register'&&<small>手机号将作为登录账号，注册即开通独立数据空间。</small>}
        {isReset&&<small>验证码有效期为 10 分钟。</small>}
      </form>
    </section>
  </div>
}

function ContactSupport({className='',label='联系客服',icon}:{className?:string;label?:string;icon?:string}){
  const[open,setOpen]=useState(false);
  return <><button type="button" className={className} onClick={()=>setOpen(true)}>{icon&&<i aria-hidden="true">{icon}</i>}{label}</button>
    {open&&createPortal(<FormModal eyebrow="WECHAT SUPPORT" title="联系客服" className="support-modal" onClose={()=>setOpen(false)}><div className="support-content"><p>咨询电子票额度、补充包购买或使用问题，请用微信扫码添加客服。</p><img src="/customer-service-wechat.png" alt="EventVivid 客服微信二维码"/><small>手机上可长按图片，在微信中识别二维码。</small></div></FormModal>,document.body)}
  </>
}
function Marketing({children}:{children:ReactNode}){return <div className="marketing"><nav><Link to="/" className="marketing-logo">EventVivid</Link><div><Link to="/#features">产品功能</Link><Link to="/pricing">价格</Link><ContactSupport className="marketing-contact-button"/><Link to="/login">登录</Link><Link className="primary link-button" to="/login?register">免费注册</Link></div></nav>{children}<footer>EventVivid · 活动发布、报名与现场验签 <div><Link to="/pricing">了解电子票额度</Link><ContactSupport className="marketing-contact-button"/></div></footer></div>}
function MarketingHome(){return <Marketing><section className="marketing-hero"><p className="kicker">EVENTS, VIVIDLY DONE</p><h1>活动从发布到入场，<br/>一处完成。</h1><p>创建活动、配置票种和报名表、生成电子票、授权工作人员验签。新租户注册赠送 100 张电子票额度，成功出票才扣减。</p><div><Link className="primary link-button" to="/login?register">免费注册</Link><Link className="link-button" to="/pricing">查看价格</Link></div></section><section className="marketing-features" id="features">{[['活动发布','基础信息、票种库存与报名页统一管理'],['报名与出票','参会人填写信息后获取电子票二维码'],['现场验签','工作人员扫码核验并查看现场统计'],['团队协作','租户成员、角色与验签点授权']].map(([title,description])=><article key={title}><h2>{title}</h2><p>{description}</p></article>)}</section></Marketing>}
function Pricing(){const packs=[{name:'注册赠送',count:100,price:'免费',note:'每个新租户一次'},{name:'小额补充包',count:100,price:'¥99',note:'试运营参考价'},{name:'常用包',count:500,price:'¥399',note:'试运营参考价'},{name:'批量包',count:2000,price:'¥1399',note:'试运营参考价'}];return <Marketing><section className="marketing-hero"><p className="kicker">SIMPLE TICKET CREDITS</p><h1>按实际出票量使用，<br/>先赠送，再补充。</h1><p>赠送和购买的电子票额度进入同一个余额，均不设使用期限。免费票、付费票每成功签发一张电子票，消耗一张额度。</p></section><section className="pricing-grid">{packs.map(pack=><article key={pack.name}><h2>{pack.name}</h2><strong>{pack.count} 张</strong><p>{pack.price}</p><small>{pack.note}</small>{pack.price==='免费'?<Link className="primary link-button" to="/login?register">注册领取</Link>:<><span className="pricing-contact">在线购买尚未开放</span><ContactSupport className="pricing-support-button" label="联系客服购买"/></>}</article>)}</section><p className="pricing-rule">不限活动数量和单场报名人数，仍受票种库存约束。所有活动数据从活动结束起统一留存 6 个月。</p></Marketing>}
function Shell({user,onLogout,children}:{user:User;onLogout:()=>void;children:ReactNode}){const nav=[{to:'/dashboard',label:'工作台',icon:'⌂'},{to:'/events',label:'活动管理',icon:'◫'},{to:'/credits',label:'额度与账单',icon:'◇'},{to:'/members',label:'团队与权限',icon:'◎'},{to:'/settings',label:'租户设置',icon:'⚙'}];return <div className="shell"><aside><div className="brand light"><b>EV</b><span>EventVivid<small>ORGANIZER</small></span></div><nav>{nav.map(item=><NavLink key={item.to} to={item.to}><i>{item.icon}</i>{item.label}</NavLink>)}<ContactSupport className="support-nav-button" icon="✆"/></nav><div className="side-note"><span>服务状态</span><b><i/> 正常运行</b><small>数据已安全同步</small></div><div className="sidebar-tenant-name" title={user.tenantName}><small>当前企业</small><strong>{user.tenantName}</strong></div><div className="profile"><span>{user.name[0]}</span><div><b>{user.name}</b><small>{user.role}</small></div><button onClick={onLogout}>退出</button></div></aside><main>{children}</main></div>}
function Header({title,subtitle,action,className=''}:{title:string;subtitle:string;action?:ReactNode;className?:string}){return <header className={`page-header ${className}`}><div><p className="kicker">EVENTVIVID ORGANIZER</p><h1>{title}</h1><p>{subtitle}</p></div>{action}</header>}
function Empty({title,desc,action}:{title:string;desc:string;action?:ReactNode}){return <div className="empty"><b>EV</b><h3>{title}</h3><p>{desc}</p>{action}</div>}
function FormModal({eyebrow,title,onClose,children,className=''}:{eyebrow:string;title:string;onClose:()=>void;children:ReactNode;className?:string}){return <div className="form-modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className={`form-modal card ${className}`} role="dialog" aria-modal="true" aria-label={title}><div className="card-head"><div><p className="kicker">{eyebrow}</p><h2>{title}</h2></div><button className="modal-close" type="button" aria-label="关闭" onClick={onClose}>×</button></div>{children}</section></div>}
function ConfirmModal({title,description,confirmLabel,busy=false,onCancel,onConfirm}:{title:string;description:string;confirmLabel:string;busy?:boolean;onCancel:()=>void;onConfirm:()=>void}){return <div className="form-modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onCancel()}}><section className="confirm-modal" role="alertdialog" aria-modal="true" aria-label={title}><div className="confirm-icon">!</div><div className="confirm-copy"><p className="kicker">CONFIRM ACTION</p><h2>{title}</h2><p>{description}</p></div><div className="confirm-actions"><button type="button" disabled={busy} onClick={onCancel}>取消</button><button className="danger-button" type="button" disabled={busy} onClick={onConfirm}>{busy?'处理中…':confirmLabel}</button></div></section></div>}
function money(cents:number){return `¥ ${(cents/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`}
const eventStatusLabels:Record<string,string>={draft:'草稿',upcoming:'未开始',published:'进行中',ended:'已结束',cancelled:'已取消'};
function eventStatusLabel(status:string){return eventStatusLabels[status]??status}
function eventDisplayStatus(event:Pick<EventItem,'status'|'starts_at'|'ends_at'>,now=Date.now()){
  if(event.status!=='published')return event.status;
  if(new Date(event.ends_at).getTime()<=now)return 'ended';
  if(new Date(event.starts_at).getTime()>now)return 'upcoming';
  return 'published';
}
function eventDateLabel(value:string){return new Date(value).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}

function EventCreditSummary({events,wallet,error,onRetry}:{events:EventItem[];wallet?:CreditWallet;error:string;onRetry:()=>void}){
  const expectedCredits=events.reduce((total,event)=>event.status==='published'&&new Date(event.ends_at).getTime()>Date.now()
    ?total+Math.max(0,Number(event.capacity)-Number(event.sold_count)):total,0);
  const remainingCredits=wallet?wallet.available-expectedCredits:null;
  const creditTone=remainingCredits===null?'':remainingCredits<10?'critical':remainingCredits<50?'low':'normal';
  return <section className={`event-credit-banner ${creditTone}`} role={creditTone==='low'||creditTone==='critical'?'status':undefined}>
    <div className="event-credit-values"><span>电子票可用额度 <strong>{wallet?`${wallet.available.toLocaleString()} 张`:error?'额度加载失败':'正在加载…'}</strong></span><span className="event-credit-expected" title="所有已公开且未结束的活动，按票种总库存减去已售数量计算">预计消耗额度 <strong>{expectedCredits.toLocaleString()} 张</strong></span></div>
    <div className="event-credit-action">{remainingCredits!==null&&creditTone!=='normal'&&<span>{remainingCredits<0?`预计消耗超过可用额度 ${Math.abs(remainingCredits).toLocaleString()} 张，建议补充。`:remainingCredits===0?'可用额度与预计消耗持平，建议补充。':`扣除预计消耗后仅余 ${remainingCredits.toLocaleString()} 张，建议补充。`}</span>}{error?<button type="button" onClick={onRetry}>重试</button>:wallet&&<ContactSupport className="event-credit-contact" label="补充额度"/>}</div>
  </section>;
}

function Dashboard(){
  const[events,setEvents]=useState<EventItem[]>([]);const[error,setError]=useState('');const[wallet,setWallet]=useState<CreditWallet>();const[creditError,setCreditError]=useState('');
  const loadCredits=()=>{setCreditError('');return api<CreditWallet>('/auth/credits').then(setWallet).catch(e=>setCreditError((e as Error).message))};
  useEffect(()=>{void api<EventItem[]>('/events').then(setEvents).catch(e=>setError((e as Error).message));void loadCredits()},[]);
  const totals=useMemo(()=>events.reduce((a,e)=>({capacity:a.capacity+Number(e.capacity),sold:a.sold+Number(e.sold_count)}),{capacity:0,sold:0}),[events]);
  return <>
    <Header title="工作台" subtitle="聚焦近期活动、报名进度和团队待办" className="events-page-header" action={<div className="events-header-actions">
      <EventCreditSummary events={events} wallet={wallet} error={creditError} onRetry={()=>void loadCredits()}/>
      <Link className="primary link-button" to="/events/new">创建活动</Link>
    </div>}/>
    {error&&<div className="alert">{error}</div>}
    <section className="metrics"><Metric label="活动总数" value={String(events.length)} note={`${events.filter(e=>eventDisplayStatus(e)==='published').length} 个进行中`}/><Metric label="累计报名" value={String(totals.sold)} note={`总容量 ${totals.capacity}`}/><Metric label="平均上座率" value={`${totals.capacity?Math.round(totals.sold/totals.capacity*100):0}%`} note="按票种容量计算"/><Metric label="待处理事项" value="0" note="审核与退款"/></section><div className="dashboard-grid"><section className="card"><div className="card-head"><div><p className="kicker">UPCOMING</p><h2>近期活动</h2></div><Link to="/events">查看全部 →</Link></div><div className="event-stack">{events.slice(0,4).map(event=><Link to={`/events/${event.id}/overview`} key={event.id} className="event-row"><time><b>{new Date(event.starts_at).getDate()}</b><small>{new Date(event.starts_at).toLocaleDateString('zh-CN',{month:'short'})}</small></time><div><h3>{event.title}</h3><p>{event.venue} · {new Date(event.starts_at).toLocaleString()}</p></div><span className={`badge ${eventDisplayStatus(event)}`}>{eventStatusLabel(eventDisplayStatus(event))}</span><strong>{event.sold_count}/{event.capacity}</strong></Link>)}{!events.length&&<Empty title="还没有活动" desc="创建第一场活动，开始配置报名和票券。"/>}</div></section><section className="card tasks"><div className="card-head"><h2>运营待办</h2><span className="badge">今日</span></div><Task title="检查待发布活动" desc="发布前确认票种、报名表和交易规则" count={events.filter(e=>e.status==='draft').length}/><Task title="关注库存进度" desc="容量超过 80% 时建议增开场次" count={0}/><Task title="准备现场验签" desc="活动前配置验签点和工作人员" count={events.filter(e=>eventDisplayStatus(e)==='published').length}/></section></div>
  </>;
}
function Metric({label,value,note}:{label:string;value:string;note:string}){return <article className="metric"><span>{label}</span><strong>{value}</strong><small>{note}</small></article>}
function Credits(){const[wallet,setWallet]=useState<CreditWallet>();const[error,setError]=useState('');useEffect(()=>{void api<CreditWallet>('/auth/credits').then(setWallet).catch(e=>setError((e as Error).message))},[]);return <><Header title="额度与账单" subtitle="所有电子票额度进入同一个余额；成功出票扣除 1 张" action={<Link className="primary link-button" to="/pricing">查看额度包</Link>}/>{error&&<div className="alert">{error}</div>}{wallet?<><section className="metrics"><Metric label="可用额度" value={String(wallet.available)} note="可供新报名"/><Metric label="订单预留" value={String(wallet.reserved)} note="未完成的报名订单"/><Metric label="账户余额" value={String(wallet.balance)} note="赠送与购买统一计算"/></section>{wallet.available<50&&<div className="notice">{wallet.available<10?'电子票额度即将用尽，请尽快联系平台补充。':'电子票额度低于 50 张，可提前了解补充包。'}</div>}<section className="card"><div className="card-head"><h2>额度流水</h2><span>最近 100 笔</span></div><table><thead><tr><th>时间</th><th>类型</th><th>张数</th><th>说明</th></tr></thead><tbody>{wallet.entries.map(entry=><tr key={entry.id}><td>{new Date(entry.created_at).toLocaleString()}</td><td>{({grant:'注册赠送',purchase:'购买',manual:'人工补发',issue:'出票消耗',return:'票券返还',refund:'退款冲减'} as Record<string,string>)[entry.kind]??entry.kind}</td><td>{entry.change>0?'+':''}{entry.change}</td><td>{entry.note}</td></tr>)}</tbody></table></section><p className="muted">活动数据从活动结束起统一留存 6 个月。当前尚未接入在线充值支付，补充额度请联系总部。</p></>:!error&&<div className="loading">正在加载额度…</div>}</>}
function Task({title,desc,count}:{title:string;desc:string;count:number}){return <article className="task"><span>{count}</span><div><b>{title}</b><p>{desc}</p></div></article>}

function localDateTime(value:string){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function EventFormModal({event,onClose,onSaved}:{event?:EventDetail;onClose:()=>void;onSaved:(saved:EventItem)=>void}){const[message,setMessage]=useState('');const[saving,setSaving]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);setSaving(true);try{const payload={title:form.get('title'),description:form.get('description'),venue:form.get('venue'),...(event?{heroColor:event.hero_color,formBackgroundColor:event.form_background_color}:{}),startsAt:form.get('startsAt'),endsAt:form.get('endsAt')};const saved=await api<EventItem>(event?`/events/${event.id}`:'/events',{method:event?'PATCH':'POST',body:JSON.stringify(payload)});onSaved(saved)}catch(e){setMessage((e as Error).message)}finally{setSaving(false)}}return <FormModal eyebrow={event?'EDIT EVENT':'NEW EVENT'} title={event?'编辑活动':'创建活动'} onClose={onClose}>{message&&<div className="alert modal-alert">{message}</div>}<form key={event?.id??'new'} onSubmit={submit}><label>活动名称<input name="title" defaultValue={event?.title??''} required minLength={2} placeholder="例如：2026 产品创新大会"/></label><div className="two"><label>开始时间<DateTimeInput name="startsAt" defaultValue={event?localDateTime(event.starts_at):''} required/></label><label>结束时间<DateTimeInput name="endsAt" defaultValue={event?localDateTime(event.ends_at):''} required/></label></div><label>活动地点<input name="venue" defaultValue={event?.venue??''} required placeholder="城市 · 场馆 · 具体地址"/></label><label>活动简介<textarea name="description" defaultValue={event?.description??''} rows={5} placeholder="介绍活动亮点、日程和适合人群"/></label><div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button className="primary" disabled={saving}>{saving?'保存中…':event?'保存修改':'创建并配置票种'}</button></div></form></FormModal>}
function PreviewButton({event,label='预览报名页'}:{event:Pick<EventItem,'id'|'slug'|'status'>;label?:string}){const[loading,setLoading]=useState(false);const[error,setError]=useState('');async function openPreview(){setError('');if(event.status==='published'){window.open(`http://localhost:5175/e/${event.slug}`,'_blank','noopener,noreferrer');return}const previewWindow=window.open('about:blank','_blank');setLoading(true);try{const result=await api<{token:string;slug:string}>(`/events/${event.id}/preview-token`,{method:'POST'});const url=`http://localhost:5175/e/${result.slug}?preview=${encodeURIComponent(result.token)}`;if(previewWindow){previewWindow.opener=null;previewWindow.location.href=url}else window.open(url,'_blank','noopener,noreferrer')}catch(e){previewWindow?.close();setError((e as Error).message)}finally{setLoading(false)}}return <button className="preview-button" type="button" disabled={loading} title={error||label} onClick={()=>void openPreview()}>{loading?'生成预览…':error?'预览失败':label}</button>}

function Events(){
  const navigate=useNavigate();const[items,setItems]=useState<EventItem[]>([]);const[query,setQuery]=useState('');const[filter,setFilter]=useState('all');const[message,setMessage]=useState('');const[creating,setCreating]=useState(false);const[unpublishing,setUnpublishing]=useState<EventItem|null>(null);const[busy,setBusy]=useState(false);
  const[wallet,setWallet]=useState<CreditWallet>();const[creditError,setCreditError]=useState('');
  const load=()=>api<EventItem[]>('/events').then(setItems);
  const loadCredits=()=>{setCreditError('');return api<CreditWallet>('/auth/credits').then(setWallet).catch(e=>setCreditError((e as Error).message))};
  useEffect(()=>{void load();void loadCredits()},[]);
  const visible=items.filter(e=>(filter==='all'||eventDisplayStatus(e)===filter)&&e.title.toLowerCase().includes(query.toLowerCase()));
  async function publish(id:string){try{await api(`/events/${id}/publish`,{method:'POST'});setMessage('活动已发布，公开报名页现已可访问。');await load()}catch(e){setMessage((e as Error).message)}}
  async function unpublish(event:EventItem){setBusy(true);try{await api(`/events/${event.id}/unpublish`,{method:'POST'});setUnpublishing(null);setMessage('活动已下线并恢复为草稿。');await load()}catch(e){setUnpublishing(null);setMessage((e as Error).message)}finally{setBusy(false)}}
  return <>
    <Header title="活动管理" subtitle="创建、发布并跟踪全部活动" className="events-page-header" action={<div className="events-header-actions">
      <EventCreditSummary events={items} wallet={wallet} error={creditError} onRetry={()=>void loadCredits()}/>
      <button className="primary link-button" onClick={()=>setCreating(true)}>+ 创建活动</button>
    </div>}/>
    {message&&<div className="notice">{message}</div>}
    <section className="card toolbar"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索活动名称"/><div className="segmented">{['all','draft','upcoming','published','ended'].map(status=><button className={filter===status?'active':''} onClick={()=>setFilter(status)} key={status}>{status==='all'?'全部':eventStatusLabel(status)}</button>)}</div></section>
    <section className="event-grid">{visible.map(event=>{
      const displayStatus=eventDisplayStatus(event);
      return <article className="event-card" key={event.id}><Link className="event-cover" to={`/events/${event.id}/overview`} aria-label={`管理活动：${event.title}`}><span className={`badge ${displayStatus}`}>{eventStatusLabel(displayStatus)}</span><b className="event-date-range">{eventDateLabel(event.starts_at)} — {eventDateLabel(event.ends_at)}</b></Link><div className="event-content"><h2>{event.title}</h2><p>{event.venue}</p><div className="progress"><span><i style={{width:`${Number(event.capacity)?Math.min(Number(event.sold_count)/Number(event.capacity)*100,100):0}%`}}/></span><small>报名 {event.sold_count}/{event.capacity}</small></div><footer><Link to={`/events/${event.id}/overview`}>管理活动</Link>{event.status==='draft'&&<button onClick={()=>publish(event.id)}>发布</button>}{(displayStatus==='published'||displayStatus==='upcoming')&&<button className="danger-text" onClick={()=>setUnpublishing(event)}>下线</button>}<PreviewButton event={event} label={event.status==='published'?'报名页':'预览'}/></footer></div></article>;
    })}{!visible.length&&<Empty title="没有匹配的活动" desc="调整筛选条件，或创建一场新活动。" action={<button className="primary" onClick={()=>setCreating(true)}>创建活动</button>}/>}</section>
    {creating&&<EventFormModal onClose={()=>setCreating(false)} onSaved={saved=>navigate(`/events/${saved.id}/tickets`)}/>}
    {unpublishing&&<ConfirmModal title={`下线活动“${unpublishing.title}”？`} description="公开报名页将立即停止访问，已有报名、订单和票券会完整保留。" confirmLabel="确认下线" busy={busy} onCancel={()=>setUnpublishing(null)} onConfirm={()=>void unpublish(unpublishing)}/>}
  </>
}

function NewEvent(){const navigate=useNavigate();return <><Header title="创建活动" subtitle="完成基础信息后继续配置票种与报名规则"/><EventFormModal onClose={()=>navigate('/events')} onSaved={saved=>navigate(`/events/${saved.id}/tickets`)}/></>}

function useEvent(){const{id=''}=useParams();const[event,setEvent]=useState<EventDetail>();const[error,setError]=useState('');const load=()=>api<EventDetail>(`/events/${id}`).then(setEvent).catch(e=>setError((e as Error).message));useEffect(()=>{void load()},[id]);return{event,error,reload:load,id}}
const tabs=[{key:'overview',label:'概览'},{key:'basic',label:'基础信息'},{key:'tickets',label:'票种库存'},{key:'form',label:'报名表'},{key:'registrations',label:'报名'},{key:'orders',label:'订单'},{key:'issued',label:'票券'},{key:'checkin',label:'现场'},{key:'reports',label:'报表'}];
function EventFrame({event,children}:{event:EventDetail;children:ReactNode}){const displayStatus=eventDisplayStatus(event);return <><div className="event-header"><div><Link to="/events">← 返回活动</Link><h1>{event.title}</h1><p>{new Date(event.starts_at).toLocaleString()} · {event.venue}</p></div><div><span className={`badge ${displayStatus}`}>{eventStatusLabel(displayStatus)}</span><PreviewButton event={event}/></div></div><nav className="event-tabs">{tabs.map(tab=><NavLink key={tab.key} to={`/events/${event.id}/${tab.key}`}>{tab.label}</NavLink>)}</nav>{children}</>}
function EventOverview(){const{event,error}=useEvent();if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载活动…</div>;const rate=event.metrics.issued?Math.round(event.metrics.checkedIn/event.metrics.issued*100):0;const formReady=(event.registration_form?.length??0)>=2;return <EventFrame event={event}><section className="metrics"><Metric label="报名人数" value={String(event.metrics.registrations)} note="全部报名记录"/><Metric label="已支付金额" value={money(event.metrics.paidAmountCents)} note="不含退款"/><Metric label="已出票" value={String(event.metrics.issued)} note="有效参会凭证"/><Metric label="验签率" value={`${rate}%`} note={`${event.metrics.checkedIn} 人已入场`}/></section><div className="dashboard-grid"><section className="card"><div className="card-head"><h2>报名进度</h2><span>{event.sold_count}/{event.capacity}</span></div><div className="large-progress"><i style={{width:`${Number(event.capacity)?Math.min(Number(event.sold_count)/Number(event.capacity)*100,100):0}%`}}/></div><div className="ticket-summary">{event.ticketTypes.map(t=><div key={t.id}><span>{t.name}</span><b>{t.sold_count}/{t.capacity}</b><small>{money(t.price_cents)}</small></div>)}</div></section><section className="card readiness"><h2>发布准备度</h2><p className="done">✓ 基础信息已填写</p><p className={event.ticketTypes.length?'done':''}>{event.ticketTypes.length?'✓':'○'} 至少配置一个票种</p><p className={formReady?'done':''}>{formReady?'✓':'○'} 报名表已配置</p><p>○ 检查退款与通知规则</p></section></div><section className="card event-links"><RegistrationLink slug={event.slug}/><CheckinLink/></section></EventFrame>}

function RegistrationLink({slug}:{slug:string}){const canvasRef=useRef<HTMLCanvasElement>(null);const[copied,setCopied]=useState(false);const registrationOrigin=import.meta.env.VITE_REGISTRATION_ORIGIN??`${window.location.protocol}//${window.location.hostname}:5175`;const url=`${registrationOrigin}/e/${slug}`;useEffect(()=>{if(canvasRef.current)void QRCode.toCanvas(canvasRef.current,url,{width:156,margin:1,color:{dark:'#17251f',light:'#ffffff'}})},[url]);async function copy(){try{await navigator.clipboard.writeText(url);setCopied(true);window.setTimeout(()=>setCopied(false),1800)}catch{setCopied(false)}}return <section className="registration-link"><div><p className="kicker">REGISTRATION LINK</p><h3>报名链接与二维码</h3><p>参会人可访问链接或扫描二维码进入报名页。</p><div className="registration-url"><code>{url}</code><button type="button" onClick={()=>void copy()}>{copied?'已复制':'复制链接'}</button></div></div><div className="registration-qr"><canvas ref={canvasRef} aria-label="报名链接二维码"/><small>扫码报名</small></div></section>}
function CheckinLink(){const canvasRef=useRef<HTMLCanvasElement>(null);const[copied,setCopied]=useState(false);const checkinOrigin=import.meta.env.VITE_CHECKIN_ORIGIN??'http://192.168.201.33:5175';const url=`${checkinOrigin}/checkin`;useEffect(()=>{if(canvasRef.current)void QRCode.toCanvas(canvasRef.current,url,{width:156,margin:1,color:{dark:'#17251f',light:'#ffffff'}})},[url]);async function copy(){try{await navigator.clipboard.writeText(url);setCopied(true);window.setTimeout(()=>setCopied(false),1800)}catch{setCopied(false)}}return <section className="registration-link checkin-link"><div><p className="kicker">CHECK-IN LINK</p><h3>现场验签链接与二维码</h3><p>工作人员可扫描二维码打开移动端验签页，登录后选择进行中的活动。</p><div className="registration-url"><code>{url}</code><button type="button" onClick={()=>void copy()}>{copied?'已复制':'复制链接'}</button></div></div><div className="registration-qr"><canvas ref={canvasRef} aria-label="现场验签链接二维码"/><small>扫码验签</small></div></section>}
function Basic(){
  const{event,error,reload}=useEvent();const[message,setMessage]=useState('');const[editing,setEditing]=useState(false);
  if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载…</div>;
  return <EventFrame event={event}>{message&&<div className="notice">{message}</div>}<section className="card event-profile"><div className="card-head"><div><p className="kicker">EVENT PROFILE</p><h2>基础信息</h2></div><button className="primary" onClick={()=>setEditing(true)}>编辑基础信息</button></div><dl><div><dt>活动名称</dt><dd>{event.title}</dd></div><div><dt>活动时间</dt><dd>{new Date(event.starts_at).toLocaleString()} — {new Date(event.ends_at).toLocaleString()}</dd></div><div><dt>活动地点</dt><dd>{event.venue}</dd></div><div><dt>活动简介</dt><dd>{event.description||'暂未填写'}</dd></div><div><dt>报名短链接</dt><dd><code>{event.slug}</code></dd></div></dl></section>{editing&&<EventFormModal event={event} onClose={()=>setEditing(false)} onSaved={()=>{setEditing(false);setMessage('基础信息已保存');void reload()}}/>}</EventFrame>
}

function Tickets(){
  const{event,error,reload}=useEvent();const[message,setMessage]=useState('');const[ticketForm,setTicketForm]=useState<TicketType|'new'|null>(null);const[ticketError,setTicketError]=useState('');const[deleting,setDeleting]=useState<TicketType|null>(null);const[busyId,setBusyId]=useState('');
  if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载…</div>;
  const eventId=event.id;
  function local(value:string){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
  async function submitTicket(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!ticketForm)return;const form=new FormData(e.currentTarget);const saleStartsAt=String(form.get('saleStartsAt')??'');const saleEndsAt=String(form.get('saleEndsAt')??'');if(new Date(saleEndsAt).getTime()<=new Date(saleStartsAt).getTime()){setTicketError('售票结束时间必须晚于开始时间');return}const editing=ticketForm==='new'?null:ticketForm;setTicketError('');setBusyId(editing?.id??'new');try{await api(editing?`/events/${eventId}/ticket-types/${editing.id}`:`/events/${eventId}/ticket-types`,{method:editing?'PATCH':'POST',body:JSON.stringify({name:form.get('name'),priceCents:Math.round(Number(form.get('price'))*100),capacity:Number(form.get('capacity')),saleStartsAt,saleEndsAt})});setTicketForm(null);setMessage(editing?'票种信息已更新':'票种已添加');await reload()}catch(e){setTicketError((e as Error).message)}finally{setBusyId('')}}
  async function remove(ticket:TicketType){if(ticket.sold_count>0)return;setBusyId(ticket.id);try{await api(`/events/${eventId}/ticket-types/${ticket.id}`,{method:'DELETE'});setDeleting(null);setMessage('未销售票种已删除');await reload()}catch(e){setDeleting(null);setMessage((e as Error).message)}finally{setBusyId('')}}
  const editing=ticketForm==='new'||ticketForm===null?null:ticketForm;
  function openTicketForm(value:TicketType|'new'){setTicketError('');setTicketForm(value)}
  function closeTicketForm(){setTicketError('');setTicketForm(null)}
  return <EventFrame event={event}>{message&&<div className="notice">{message}</div>}<section className="card"><div className="card-head"><div><p className="kicker">INVENTORY</p><h2>票种与库存</h2></div><div className="head-actions"><span>{event.ticketTypes.length} 个票种</span><button className="primary" onClick={()=>openTicketForm('new')}>+ 添加票种</button></div></div><div className="ticket-list">{event.ticketTypes.map(t=><article key={t.id}><div><b>{t.name}</b><span>{money(t.price_cents)}</span></div><div className="stock"><span><i style={{width:`${t.capacity?Math.min(t.sold_count/t.capacity*100,100):0}%`}}/></span><small>已售 {t.sold_count} / {t.capacity}</small></div><footer><span>{new Date(t.sale_starts_at).toLocaleDateString()} — {new Date(t.sale_ends_at).toLocaleDateString()}</span><div className="ticket-actions"><button onClick={()=>openTicketForm(t)}>编辑</button><button className="danger-text" disabled={t.sold_count>0||busyId===t.id} title={t.sold_count>0?'已有销售记录，不能删除':''} onClick={()=>setDeleting(t)}>{busyId===t.id?'处理中…':'删除'}</button></div></footer></article>)}{!event.ticketTypes.length&&<Empty title="尚未配置票种" desc="添加至少一个票种后才可发布活动。" action={<button className="primary" onClick={()=>openTicketForm('new')}>添加第一个票种</button>}/>}</div></section>{ticketForm&&<FormModal eyebrow={editing?'EDIT TICKET':'NEW TICKET'} title={editing?'编辑票种':'添加票种'} onClose={closeTicketForm}>{ticketError&&<div className="alert modal-alert" role="alert">{ticketError}</div>}<form key={editing?.id??'new'} onSubmit={submitTicket}><label>票种名称<input name="name" defaultValue={editing?.name??''} required placeholder="标准票"/></label><div className="two"><label>价格（元）<input name="price" type="number" min="0" step="0.01" defaultValue={editing?editing.price_cents/100:''} required/></label><label>库存<input name="capacity" type="number" min={Math.max(1,editing?.sold_count??0)} defaultValue={editing?.capacity??''} required/>{editing&&<small>不能低于已售 {editing.sold_count}</small>}</label></div><label>开售时间<DateTimeInput name="saleStartsAt" defaultValue={editing?local(editing.sale_starts_at):''} required/></label><label>停售时间<DateTimeInput name="saleEndsAt" defaultValue={editing?local(editing.sale_ends_at):''} required/></label><div className="modal-actions"><button type="button" onClick={closeTicketForm}>取消</button><button className="primary" disabled={busyId===(editing?.id??'new')}>{busyId===(editing?.id??'new')?'保存中…':editing?'保存修改':'添加票种'}</button></div></form></FormModal>}{deleting&&<ConfirmModal title={`删除票种“${deleting.name}”？`} description="删除后无法恢复。只有尚未销售且没有报名记录的票种可以删除。" confirmLabel="确认删除" busy={busyId===deleting.id} onCancel={()=>setDeleting(null)} onConfirm={()=>void remove(deleting)}/>}</EventFrame>
}

function RegistrationFormPage(){
  const{event,error,reload}=useEvent();const[fields,setFields]=useState<RegistrationField[]>([]);const[fieldForm,setFieldForm]=useState<RegistrationField|'new'|null>(null);const[styleForm,setStyleForm]=useState(false);const[fieldType,setFieldType]=useState<RegistrationField['type']>('text');const[message,setMessage]=useState('');const[saving,setSaving]=useState(false);const[styleSaving,setStyleSaving]=useState(false);
  useEffect(()=>{if(event)setFields(event.registration_form??[])},[event]);
  if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载…</div>;
  const eventId=event.id;
  function update(id:string,patch:Partial<RegistrationField>){setFields(current=>current.map(field=>field.id===id?{...field,...patch}:field));setMessage('')}
  function move(index:number,direction:-1|1){const target=index+direction;if(target<0||target>=fields.length)return;setFields(current=>{const next=[...current];const source=next[index];const destination=next[target];if(!source||!destination)return current;next[index]=destination;next[target]=source;return next});setMessage('')}
  function remove(field:RegistrationField){if(field.system)return;setFields(current=>current.filter(item=>item.id!==field.id));setMessage('')}
  function openFieldForm(value:RegistrationField|'new'){setFieldType(value==='new'?'text':value.type);setFieldForm(value);setMessage('')}
  function submitField(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);const editing=fieldForm==='new'||fieldForm===null?null:fieldForm;const type=editing?.system?editing.type:fieldType;const options=type==='select'?String(form.get('options')??'').split(/[,，\n]/).map(item=>item.trim()).filter(Boolean):[];if(type==='select'&&!options.length){setMessage('下拉选择字段至少需要一个选项');return}const field:RegistrationField={id:editing?.id??crypto.randomUUID(),key:editing?.key??`custom_${Date.now()}`,label:String(form.get('label')??'').trim(),type,required:editing?.key==='name'||editing?.key==='mobile'?true:form.get('required')==='on',enabled:editing?.enabled??true,system:editing?.system??false,placeholder:String(form.get('placeholder')??'').trim(),options};setFields(current=>editing?current.map(item=>item.id===editing.id?field:item):[...current,field]);setFieldForm(null);setMessage('')}
  async function save(){setSaving(true);setMessage('');try{await api(`/events/${eventId}/registration-form`,{method:'PATCH',body:JSON.stringify({fields})});setMessage('报名表配置已保存，报名页面将立即使用新表单。')}catch(e){setMessage((e as Error).message)}finally{setSaving(false)}}
  async function saveStyle(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);setStyleSaving(true);try{await api(`/events/${eventId}/registration-style`,{method:'PATCH',body:JSON.stringify({heroColor:form.get('heroColor'),formBackgroundColor:form.get('formBackgroundColor')})});setStyleForm(false);setMessage('报名页样式已保存');await reload()}catch(e){setMessage((e as Error).message)}finally{setStyleSaving(false)}}
  const editing=fieldForm==='new'||fieldForm===null?null:fieldForm;
  return <EventFrame event={event}><div className="form-builder-head"><div><p className="kicker">REGISTRATION FORM</p><h2>报名表配置</h2><p>配置参会人报名时需要填写的信息，姓名和手机号为核心字段。</p></div><div><button onClick={()=>setStyleForm(true)}>样式</button><button onClick={()=>openFieldForm('new')}>+ 添加字段</button><button className="primary" disabled={saving} onClick={()=>void save()}>{saving?'保存中…':'保存配置'}</button></div></div>{message&&<div className={message.includes('已保存')?'notice':'alert'}>{message}</div>}<div className="form-builder"><section className="card field-panel"><div className="card-head"><h3>表单字段</h3><span>{fields.filter(field=>field.enabled).length} 个已启用</span></div><div className="field-list">{fields.map((field,index)=><article className={!field.enabled?'disabled':''} key={field.id}><div className="field-order"><button disabled={index===0} onClick={()=>move(index,-1)}>↑</button><button disabled={index===fields.length-1} onClick={()=>move(index,1)}>↓</button></div><div className="field-info"><b>{field.label}{field.required&&<em>*</em>}</b><small>{({text:'单行文本',mobile:'手机号',email:'邮箱',number:'数字',select:'下拉选择',textarea:'多行文本'} as Record<string,string>)[field.type]} · {field.key}</small></div><label className="mini-switch"><input type="checkbox" checked={field.enabled} disabled={field.key==='name'||field.key==='mobile'} onChange={e=>update(field.id,{enabled:e.target.checked})}/><span>启用</span></label><label className="mini-switch"><input type="checkbox" checked={field.required} disabled={field.key==='name'||field.key==='mobile'} onChange={e=>update(field.id,{required:e.target.checked})}/><span>必填</span></label><div className="field-actions"><button onClick={()=>openFieldForm(field)}>编辑</button>{!field.system&&<button className="danger-text" onClick={()=>remove(field)}>删除</button>}</div></article>)}</div></section><section className="card form-preview"><div className="card-head"><div><p className="kicker">LIVE PREVIEW</p><h3>报名页预览</h3></div><span>移动端</span></div><div className="preview-phone"><header className="preview-hero" style={{background:event.hero_color}}><small>EVENTVIVID PRESENTS</small><b>{event.title}</b><span>{event.venue}</span></header><div className="preview-form" style={{background:event.form_background_color}}><h4>填写报名信息</h4><label>选择票种<select disabled><option>标准票</option></select></label>{fields.filter(field=>field.enabled).map(field=><label key={field.id}><span>{field.label}{field.required&&<em>*</em>}{!field.required&&<small>（选填）</small>}</span>{field.type==='textarea'?<textarea disabled rows={3} placeholder={field.placeholder}/>:field.type==='select'?<select disabled><option>{field.placeholder||'请选择'}</option>{field.options?.map(option=><option key={option}>{option}</option>)}</select>:<input disabled type={field.type==='email'?'email':field.type==='number'?'number':'text'} min={field.type==='number'?0:undefined} placeholder={field.placeholder}/>}</label>)}<button className="primary" disabled>确认报名</button></div></div></section></div>{styleForm&&<FormModal eyebrow="REGISTRATION STYLE" title="报名页样式" onClose={()=>setStyleForm(false)}><form onSubmit={saveStyle}><label>头部背景色<input name="heroColor" type="color" defaultValue={event.hero_color}/></label><label>表单背景色<input name="formBackgroundColor" type="color" defaultValue={event.form_background_color}/></label><div className="modal-actions"><button type="button" onClick={()=>setStyleForm(false)}>取消</button><button className="primary" disabled={styleSaving}>{styleSaving?'保存中…':'保存样式'}</button></div></form></FormModal>}{fieldForm&&<FormModal eyebrow={editing?'EDIT FIELD':'NEW FIELD'} title={editing?'编辑报名字段':'添加报名字段'} onClose={()=>setFieldForm(null)}><form key={editing?.id??'new'} onSubmit={submitField}><label>字段名称<input name="label" defaultValue={editing?.label??''} required placeholder="例如：公司名称"/></label><label>字段类型<select name="type" value={fieldType} onChange={e=>setFieldType(e.target.value as RegistrationField['type'])} disabled={Boolean(editing?.system)}><option value="text">单行文本</option><option value="textarea">多行文本</option><option value="number">数字</option><option value="email">邮箱</option><option value="mobile">手机号</option><option value="select">下拉选择</option></select></label><label>输入提示<input name="placeholder" defaultValue={editing?.placeholder??''} placeholder="显示在输入框中的提示"/></label>{fieldType==='select'&&<label>下拉选项<textarea name="options" rows={3} defaultValue={editing?.options?.join('\n')??''} placeholder="每行一个选项" required/></label>}<label className="required-check"><input name="required" type="checkbox" defaultChecked={editing?.required??false} disabled={editing?.key==='name'||editing?.key==='mobile'}/><span>设为必填字段</span></label><div className="modal-actions"><button type="button" onClick={()=>setFieldForm(null)}>取消</button><button className="primary">{editing?'保存修改':'添加字段'}</button></div></form></FormModal>}</EventFrame>
}

const statusLabels:Record<string,string>={pending:'待处理',confirmed:'已确认',cancelled:'已取消',rejected:'已拒绝',paid:'已支付',unpaid:'待支付',refunded:'已退款',failed:'失败',issued:'已出票',valid:'有效',checked_in:'已验签',voided:'已作废'};
function statusLabel(value:unknown){const status=String(value??'');return statusLabels[status]??status??'-'}
function statusTone(value:unknown){const status=String(value??'');if(['confirmed','paid','valid','issued','checked_in'].includes(status))return 'status-success';if(['cancelled','rejected','refunded','failed','voided'].includes(status))return 'status-danger';return 'status-pending'}
function DataPage({kind}:{kind:'registrations'|'orders'|'issued'}){
  const{event,error,id}=useEvent();const[rows,setRows]=useState<Array<Record<string,unknown>>>([]);const[query,setQuery]=useState('');
  useEffect(()=>{if(id)void api<Array<Record<string,unknown>>>(`/events/${id}/${kind==='issued'?'issued-tickets':kind}`).then(setRows)},[id,kind]);
  if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载…</div>;
  const config={registrations:{title:'报名管理',desc:'查看参会人、票种、报名和订单状态'},orders:{title:'订单与退款',desc:'查看订单金额、支付结果和交易时间'},issued:{title:'票券管理',desc:'查询电子票、验签状态和参会人'}}[kind];
  const normalized=query.trim().toLowerCase();const visible=normalized?rows.filter(row=>Object.values(row).some(value=>String(value??'').toLowerCase().includes(normalized))):rows;
  function exportData(){const headers=kind==='registrations'?['参会人','手机号','票种','报名状态','订单状态','报名时间']:kind==='orders'?['订单号','参会人','手机号','金额（分）','订单状态','创建时间']:['票码','参会人','手机号','票券状态','验签时间','出票时间'];const keys=kind==='registrations'?['attendee_name','attendee_mobile','ticket_type_name','status','order_status','created_at']:kind==='orders'?['order_no','attendee_name','attendee_mobile','amount_cents','status','created_at']:['code','attendee_name','attendee_mobile','status','checked_in_at','created_at'];const csv=[headers,...visible.map(row=>keys.map(key=>['status','order_status'].includes(key)?statusLabel(row[key]):String(row[key]??'')))].map(line=>line.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([`\uFEFF${csv}`],{type:'text/csv;charset=utf-8'}));link.download=`${config.title}-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(link.href)}
  return <EventFrame event={event}><section className="card data-card"><div className="card-head"><div><p className="kicker">EVENT DATA</p><h2>{config.title}</h2><p>{config.desc}</p></div><div className="data-tools"><label className="data-search"><span aria-hidden="true">⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} aria-label="搜索列表" placeholder="搜索姓名、手机号或单号"/>{query&&<button type="button" aria-label="清空搜索" onClick={()=>setQuery('')}>×</button>}</label><button className="export-button" type="button" onClick={exportData} disabled={!visible.length}><span aria-hidden="true">↓</span>导出数据</button></div></div>{visible.length?<table><thead><tr>{kind==='registrations'?<><th>参会人</th><th>票种</th><th>报名状态</th><th>订单状态</th><th>报名时间</th></>:kind==='orders'?<><th>订单号</th><th>参会人</th><th>金额</th><th>状态</th><th>创建时间</th></>:<><th>票码</th><th>参会人</th><th>状态</th><th>验签时间</th><th>出票时间</th></>}</tr></thead><tbody>{visible.map((row,index)=><tr key={String(row.id??index)}>{kind==='registrations'?<><td><b>{String(row.attendee_name)}</b><small>{String(row.attendee_mobile)}</small></td><td>{String(row.ticket_type_name)}</td><td><span className={`badge ${statusTone(row.status)}`}>{statusLabel(row.status)}</span></td><td><span className={`badge ${statusTone(row.order_status)}`}>{statusLabel(row.order_status)}</span></td><td>{new Date(String(row.created_at)).toLocaleString()}</td></>:kind==='orders'?<><td><code>{String(row.order_no)}</code></td><td><b>{String(row.attendee_name)}</b><small>{String(row.attendee_mobile)}</small></td><td>{money(Number(row.amount_cents))}</td><td><span className={`badge ${statusTone(row.status)}`}>{statusLabel(row.status)}</span></td><td>{new Date(String(row.created_at)).toLocaleString()}</td></>:<><td><code>{String(row.code)}</code></td><td><b>{String(row.attendee_name)}</b><small>{String(row.attendee_mobile)}</small></td><td><span className={`badge ${statusTone(row.status)}`}>{statusLabel(row.status)}</span></td><td>{row.checked_in_at?new Date(String(row.checked_in_at)).toLocaleString():'-'}</td><td>{new Date(String(row.created_at)).toLocaleString()}</td></>}</tr>)}</tbody></table>:<Empty title={query?'没有匹配的数据':`暂无${config.title}数据`} desc={query?'请调整搜索关键词后重试。':'数据将在参会人完成对应流程后出现在这里。'}/>}</section></EventFrame>
}

function Checkin(){const{event,error}=useEvent();const[stats,setStats]=useState<{issued:number;checkedIn:number}>();const[points,setPoints]=useState<CheckinPoint[]>([]);const[staff,setStaff]=useState<CheckinStaff[]>([]);const[message,setMessage]=useState('');const[loading,setLoading]=useState(false);const[pointForm,setPointForm]=useState<CheckinPoint|'new'|null>(null);const[authorizing,setAuthorizing]=useState<CheckinPoint|null>(null);const load=async(id:string)=>{const[pointData,staffData,statsData]=await Promise.all([api<CheckinPoint[]>(`/checkins/points/${id}`),api<CheckinStaff[]>(`/checkins/staff/${id}`),api<{issued:number;checkedIn:number}>(`/checkins/stats/${id}`)]);setPoints(pointData);setStaff(staffData);setStats(statsData)};useEffect(()=>{if(event)void load(event.id).catch(e=>setMessage((e as Error).message))},[event]);async function savePoint(e:FormEvent<HTMLFormElement>){if(!event||!pointForm)return;e.preventDefault();const form=new FormData(e.currentTarget);setLoading(true);setMessage('');try{await api(pointForm==='new'?`/checkins/points/${event.id}`:`/checkins/points/${pointForm.id}`,{method:pointForm==='new'?'POST':'PATCH',body:JSON.stringify({name:form.get('name')})});setPointForm(null);await load(event.id);setMessage(pointForm==='new'?'验签点已创建':'验签点名称已更新')}catch(e){setMessage((e as Error).message)}finally{setLoading(false)}}async function toggle(point:CheckinPoint){if(!event)return;setLoading(true);setMessage('');try{await api(`/checkins/points/${point.id}`,{method:'PATCH',body:JSON.stringify({active:!point.active})});await load(event.id);setMessage(point.active?'验签点已停用':'验签点已启用')}catch(e){setMessage((e as Error).message)}finally{setLoading(false)}}async function saveStaff(e:FormEvent<HTMLFormElement>){if(!event||!authorizing)return;e.preventDefault();const form=new FormData(e.currentTarget);const userIds=staff.filter(member=>member.can_checkin&&form.get(`staff_${member.id}`)==='on').map(member=>member.id);setLoading(true);setMessage('');try{await api(`/checkins/points/${authorizing.id}/staff`,{method:'PUT',body:JSON.stringify({userIds})});setAuthorizing(null);await load(event.id);setMessage('工作人员授权已保存')}catch(e){setMessage((e as Error).message)}finally{setLoading(false)}}if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载…</div>;const eligible=staff.filter(member=>member.can_checkin);const assignedCount=new Set(points.flatMap(point=>point.staff.map(member=>member.id))).size;return <EventFrame event={event}>{message&&<div className={message.includes('已')?'notice':'alert'}>{message}</div>}<section className="metrics"><Metric label="已出票" value={String(stats?.issued??event.metrics.issued)} note="可核验票券"/><Metric label="已验签" value={String(stats?.checkedIn??event.metrics.checkedIn)} note="累计入场"/><Metric label="未验签" value={String((stats?.issued??event.metrics.issued)-(stats?.checkedIn??event.metrics.checkedIn))} note="尚未入场"/><Metric label="验签率" value={`${stats?.issued?Math.round(stats.checkedIn/stats.issued*100):0}%`} note="实时数据"/></section><div className="content-split"><section className="card"><div className="card-head"><div><p className="kicker">CHECK-IN POINTS</p><h2>验签点管理</h2></div><button className="primary" onClick={()=>setPointForm('new')}>+ 新建验签点</button></div><p className="muted">为入口、分会场等现场区域创建独立验签点，并分别授权工作人员。</p><div className="checkin-points">{points.map(point=><article className="checkin-point" key={point.id}><div><b>{point.name}</b><small>{point.active?'正常服务中':'已停用，无法验签'}</small></div><span className={`badge ${point.active?'published':'cancelled'}`}>{point.active?'已启用':'已停用'}</span><div className="checkin-staff-summary"><b>已授权工作人员</b>{point.staff.length?<span>{point.staff.map(member=>member.name).join('、')}</span>:<span className="muted">暂未授权</span>}</div><footer><button onClick={()=>setPointForm(point)}>编辑名称</button><button onClick={()=>setAuthorizing(point)}>工作人员授权</button><button className={point.active?'danger-text':''} disabled={loading} onClick={()=>void toggle(point)}>{point.active?'停用':'启用'}</button></footer></article>)}{!points.length&&<Empty title="尚未创建验签点" desc="创建入口或会场验签点后，再授权工作人员使用。" action={<button className="primary" onClick={()=>setPointForm('new')}>创建验签点</button>}/>}</div></section><section className="card readiness"><h2>现场准备清单</h2><p className={points.length?'done':''}>{points.length?'✓':'○'} 已创建 {points.length} 个验签点</p><p className={assignedCount?'done':''}>{assignedCount?'✓':'○'} 已授权 {assignedCount} 名工作人员</p><p className={eligible.length?'done':''}>{eligible.length?'✓':'○'} {eligible.length} 名成员拥有现场验签权限</p><p>○ 到现场测试扫码设备与网络</p><a className="button" href="http://localhost:5175/checkin" target="_blank" rel="noreferrer">打开工作人员验签页</a><small className="muted">工作人员需使用活动平台账号登录，且获得对应验签点授权后才能执行验签。</small></section></div>{pointForm&&<FormModal eyebrow={pointForm==='new'?'NEW CHECK-IN POINT':'EDIT CHECK-IN POINT'} title={pointForm==='new'?'新建验签点':'编辑验签点'} onClose={()=>setPointForm(null)}><form key={pointForm==='new'?'new':pointForm.id} onSubmit={savePoint}><label>验签点名称<input name="name" required minLength={2} maxLength={50} defaultValue={pointForm==='new'?'':pointForm.name} placeholder="例如：主入口、VIP 通道、A 厅入口"/></label><p className="muted">停用的验签点不会接受工作人员的扫码验签。</p><div className="modal-actions"><button type="button" onClick={()=>setPointForm(null)}>取消</button><button className="primary" disabled={loading}>{loading?'保存中…':pointForm==='new'?'创建验签点':'保存修改'}</button></div></form></FormModal>}{authorizing&&<FormModal eyebrow="STAFF AUTHORIZATION" title={`授权工作人员 · ${authorizing.name}`} onClose={()=>setAuthorizing(null)}><form onSubmit={saveStaff}><p className="muted">仅列出拥有“现场验签管理”权限且账号正常的成员。勾选后，该成员可以在此验签点核验票券。</p><div className="authorization-list">{eligible.map(member=><label key={member.id}><input name={`staff_${member.id}`} type="checkbox" defaultChecked={authorizing.staff.some(item=>item.id===member.id)}/><span><b>{member.name}</b><small>{member.mobile??'未设置手机号'} · {roleLabels[member.role]??member.role}</small></span></label>)}{!eligible.length&&<p className="alert">暂无可授权成员。请先在“团队与权限”为成员授予“现场验签管理”权限。</p>}</div><div className="modal-actions"><button type="button" onClick={()=>setAuthorizing(null)}>取消</button><button className="primary" disabled={loading||!eligible.length}>{loading?'保存中…':'保存授权'}</button></div></form></FormModal>}</EventFrame>}
function Reports(){const{event,error}=useEvent();if(error)return <div className="alert">{error}</div>;if(!event)return <div className="loading">正在加载…</div>;const conversion=Number(event.capacity)?Math.round(Number(event.sold_count)/Number(event.capacity)*100):0;return <EventFrame event={event}><section className="metrics"><Metric label="容量利用率" value={`${conversion}%`} note="已报名 / 总容量"/><Metric label="支付收入" value={money(event.metrics.paidAmountCents)} note="当前已支付订单"/><Metric label="出票转化" value={`${event.metrics.registrations?Math.round(event.metrics.issued/event.metrics.registrations*100):0}%`} note="出票 / 报名"/><Metric label="现场到场率" value={`${event.metrics.issued?Math.round(event.metrics.checkedIn/event.metrics.issued*100):0}%`} note="验签 / 出票"/></section><section className="card report-placeholder"><div><p className="kicker">REGISTRATION TREND</p><h2>报名趋势</h2></div><div className="bars">{[22,35,28,49,67,54,82,72,93,76,100,88].map((h,i)=><i style={{height:`${h}%`}} key={i}/>)}</div><p>完整报表将在接入渠道事件与每日聚合任务后展示。</p></section></EventFrame>}
const roleLabels:Record<string,string>={tenant_admin:'租户管理员',event_manager:'活动运营',checkin_staff:'现场验签员',viewer:'数据查看员'};
const permissionOptions:Array<{value:Permission;label:string}>= [{value:'events.manage',label:'活动与票种管理'},{value:'registrations.view',label:'查看报名数据'},{value:'orders.view',label:'查看订单数据'},{value:'checkin.manage',label:'现场验签管理'},{value:'reports.view',label:'查看活动报表'},{value:'members.manage',label:'团队成员管理'}];
const allPermissions=permissionOptions.map(item=>item.value);
const rolePermissionTemplates:Record<string,Permission[]>={tenant_admin:allPermissions,event_manager:['events.manage','registrations.view','orders.view','reports.view'],checkin_staff:['checkin.manage'],viewer:['registrations.view','orders.view','reports.view']};
function MemberFormModal({member,onClose,onSaved}:{member?:Member;onClose:()=>void;onSaved:()=>void}){const[message,setMessage]=useState('');const[saving,setSaving]=useState(false);const[role,setRole]=useState(member?.role??'event_manager');const[permissions,setPermissions]=useState<Permission[]>(member?.role==='tenant_admin'?allPermissions:(member?.permissions?.length?member.permissions:rolePermissionTemplates[member?.role??'event_manager']??[]));function changeRole(next:string){setRole(next);setPermissions(rolePermissionTemplates[next]??[])}function togglePermission(permission:Permission){if(role==='tenant_admin')return;setPermissions(current=>current.includes(permission)?current.filter(item=>item!==permission):[...current,permission])}async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);setSaving(true);setMessage('');try{const payload={name:form.get('name'),role,permissions,...(member?{status:form.get('status'),password:form.get('password')}:{mobile:form.get('mobile'),password:form.get('password')})};await api(member?`/auth/members/${member.id}`:'/auth/members',{method:member?'PATCH':'POST',body:JSON.stringify(payload)});onSaved()}catch(e){setMessage((e as Error).message)}finally{setSaving(false)}}return <FormModal eyebrow={member?'EDIT MEMBER':'NEW MEMBER'} title={member?'编辑成员与权限':'添加团队成员'} onClose={onClose}>{message&&<div className="alert modal-alert">{message}</div>}<form key={member?.id??'new'} onSubmit={submit}><label>成员姓名<input name="name" required minLength={2} defaultValue={member?.name??''} placeholder="例如：李四"/></label>{member?<label>手机号<input value={member.mobile??member.username??''} disabled/></label>:<label>手机号<input name="mobile" type="tel" required pattern="1[3-9][0-9]{9}" placeholder="请输入 11 位手机号"/></label>}<label>角色<select name="role" value={role} onChange={e=>changeRole(e.target.value)}>{Object.entries(roleLabels).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><fieldset className="permission-grid"><legend>功能权限</legend><small>切换角色将重置为该角色的推荐权限，可按需微调。</small>{permissionOptions.map(item=><label key={item.value}><input type="checkbox" checked={permissions.includes(item.value)} disabled={role==='tenant_admin'} onChange={()=>togglePermission(item.value)}/><span>{item.label}</span></label>)}</fieldset>{member&&<label>账号状态<select name="status" defaultValue={member.status}><option value="active">正常</option><option value="disabled">已停用</option></select></label>}<label>{member?'重置密码（留空则不修改）':'初始密码'}<input name="password" type="password" required={!member} minLength={8} autoComplete="new-password" placeholder="至少 8 位"/></label><div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button className="primary" disabled={saving}>{saving?'保存中…':member?'保存修改':'添加成员'}</button></div></form></FormModal>}
function Members(){const[items,setItems]=useState<Member[]>([]);const[error,setError]=useState('');const[editing,setEditing]=useState<Member|'new'|null>(null);const[deleting,setDeleting]=useState<Member|null>(null);const[busy,setBusy]=useState(false);const load=()=>api<Member[]>('/auth/members').then(setItems).catch(e=>setError((e as Error).message));useEffect(()=>{void load()},[]);async function remove(){if(!deleting)return;setBusy(true);try{await api(`/auth/members/${deleting.id}`,{method:'DELETE'});setDeleting(null);await load()}catch(e){setError((e as Error).message);setDeleting(null)}finally{setBusy(false)}}return <><Header title="团队与权限" subtitle="管理租户成员、角色和活动授权" action={<button className="primary" onClick={()=>setEditing('new')}>添加成员</button>}/>{error&&<div className="alert">{error}</div>}<section className="card">{items.length?<table><thead><tr><th>成员</th><th>手机号</th><th>角色</th><th>权限</th><th>状态</th><th>最近登录</th><th/></tr></thead><tbody>{items.map(member=><tr key={member.id}><td><b>{member.name}</b></td><td>{member.mobile??member.username??'-'}</td><td>{roleLabels[member.role]??member.role}</td><td>{member.role==='tenant_admin'?'全部权限':`${member.permissions?.length??0} 项权限`}</td><td><span className={`badge ${member.status==='active'?'published':'cancelled'}`}>{member.status==='active'?'正常':'已停用'}</span></td><td>{member.last_login_at?new Date(member.last_login_at).toLocaleString():'从未登录'}</td><td><div className="member-actions"><button onClick={()=>setEditing(member)}>编辑</button><button className="danger-text" onClick={()=>setDeleting(member)}>删除</button></div></td></tr>)}</tbody></table>:<Empty title="暂无团队成员" desc="添加成员后可在此管理角色和权限。" action={<button className="primary" onClick={()=>setEditing('new')}>添加成员</button>}/>}</section>{editing&&<MemberFormModal member={editing==='new'?undefined:editing} onClose={()=>setEditing(null)} onSaved={()=>{setEditing(null);void load()}}/>}{deleting&&<ConfirmModal title={`删除成员“${deleting.name}”？`} description="删除后该成员将无法再登录活动平台。已有历史操作记录的成员请改为停用。" confirmLabel="确认删除" busy={busy} onCancel={()=>setDeleting(null)} onConfirm={()=>void remove()}/>}</>}
function ChangePasswordForm(){const[message,setMessage]=useState('');const[saving,setSaving]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const formElement=e.currentTarget;const form=new FormData(formElement);const newPassword=String(form.get('newPassword')??'');if(newPassword!==String(form.get('confirmPassword')??'')){setMessage('两次输入的新密码不一致');return}setSaving(true);setMessage('');try{const result=await api<{message:string}>('/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:form.get('currentPassword'),newPassword,confirmPassword:form.get('confirmPassword')})});formElement.reset();setMessage(result.message)}catch(e){setMessage((e as Error).message)}finally{setSaving(false)}}return <section className="card editor password-card"><div><p className="kicker">ACCOUNT SECURITY</p><h2>修改密码</h2><p>修改后请妥善保管新密码。</p></div><form onSubmit={submit}><label>当前密码<input name="currentPassword" type="password" required minLength={8} autoComplete="current-password"/></label><label>新密码<input name="newPassword" type="password" required minLength={8} autoComplete="new-password" placeholder="至少 8 位"/></label><label>确认新密码<input name="confirmPassword" type="password" required minLength={8} autoComplete="new-password"/></label>{message&&<div className={message==='密码已修改'?'notice':'alert'}>{message}</div>}<button className="primary" disabled={saving}>{saving?'保存中…':'更新密码'}</button></form></section>}
function Settings(){const[settings,setSettings]=useState<TenantSettings>();const[message,setMessage]=useState('');const[saving,setSaving]=useState(false);useEffect(()=>{void api<TenantSettings>('/auth/tenant').then(setSettings).catch(e=>setMessage((e as Error).message))},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);setSaving(true);setMessage('');try{const saved=await api<TenantSettings>('/auth/tenant',{method:'PATCH',body:JSON.stringify({name:form.get('name'),supportContact:form.get('supportContact'),timezone:form.get('timezone')})});setSettings(saved);setMessage('租户设置已保存')}catch(e){setMessage((e as Error).message)}finally{setSaving(false)}}if(!settings)return <div className="loading">正在加载租户设置…</div>;return <><Header title="租户设置" subtitle="管理企业资料、品牌和默认业务规则"/>{message&&<div className={message==='租户设置已保存'?'notice':'alert'}>{message}</div>}<div className="dashboard-grid settings-dashboard"><section className="card editor"><h2>企业资料</h2><form key={settings.id} onSubmit={submit}><label>企业名称<input name="name" required minLength={2} defaultValue={settings.name}/></label><label>客服联系方式<input name="supportContact" defaultValue={settings.support_contact} placeholder="400-000-0000"/></label><label>默认时区<select name="timezone" defaultValue={settings.timezone}><option value="Asia/Shanghai">Asia/Shanghai</option></select></label><button className="primary" disabled={saving}>{saving?'保存中…':'保存设置'}</button></form></section><section className="card readiness"><h2>安全与服务</h2><p className="done">✓ 租户数据隔离已启用</p><p className={settings.status==='active'?'done':''}>{settings.status==='active'?'✓':'○'} 租户服务{settings.status==='active'?'正常':'已停用'}</p><p>○ 配置微信支付渠道</p><p>○ 配置短信签名</p></section></div><ChangePasswordForm/></>}

export function App(){const[user,setUser]=useState<User|null>(null);const[checking,setChecking]=useState(Boolean(session.get()));const navigate=useNavigate();const location=useLocation();useEffect(()=>{if(!session.get()){setChecking(false);return}void api<User>('/auth/me').then(setUser).catch(()=>session.clear()).finally(()=>setChecking(false))},[]);function logout(){session.clear();setUser(null);navigate('/login')}if(checking)return <div className="loading full">正在恢复活动工作空间…</div>;if(location.pathname==='/')return <MarketingHome/>;if(location.pathname==='/pricing')return <Pricing/>;if(location.pathname==='/login')return user?<Navigate to="/dashboard"/>:<Login onLogin={value=>{setUser(value);navigate('/dashboard')}}/>;if(!user)return <Navigate to="/login"/>;return <Shell user={user} onLogout={logout}><Routes><Route path="/dashboard" element={<Dashboard/>}/><Route path="/events" element={<Events/>}/><Route path="/events/new" element={<NewEvent/>}/><Route path="/events/:id/overview" element={<EventOverview/>}/><Route path="/events/:id/basic" element={<Basic/>}/><Route path="/events/:id/tickets" element={<Tickets/>}/><Route path="/events/:id/form" element={<RegistrationFormPage/>}/><Route path="/events/:id/registrations" element={<DataPage kind="registrations"/>}/><Route path="/events/:id/orders" element={<DataPage kind="orders"/>}/><Route path="/events/:id/issued" element={<DataPage kind="issued"/>}/><Route path="/events/:id/checkin" element={<Checkin/>}/><Route path="/events/:id/reports" element={<Reports/>}/><Route path="/members" element={<Members/>}/><Route path="/credits" element={<Credits/>}/><Route path="/settings" element={<Settings/>}/><Route path="*" element={<Navigate to="/dashboard"/>}/></Routes></Shell>}
